corrected_code:
const express = require('express');
const router = express.Router();

router.delete('/auth/passkeys/devices/:credentialId', requireAuth, async (req, res) => {
  const { credentialId } = req.params;

  const result = await knex('user_security_keys')
    .where({
      credential_id: credentialId,
      user_id: req.user.id
    })
    .del();

  if (!result) {
    return res.status(403).json({ error: 'Security key not found or unauthorized' });
  }

  return res.json({ status: 'unregistered', credentialId });
});
